using System;
using System.Linq;
using NeedForValheim;
using UnityEngine;
class Program {
    static int checks;
    static void Check(bool condition,string name){if(!condition)throw new Exception(name);checks++;}
    static void Main() {
        for(int layout=0;layout<4;layout++) {
            Check(VehicleStorageRules.Capacity(false,layout)==24-layout*6,"350Z capacity");
            Check(VehicleStorageRules.Capacity(true,layout)==32,"H2 fixed capacity");
        }
        Check(VehicleStorageRules.Capacity(false,-50)==24&&VehicleStorageRules.Capacity(false,99)==6,"configuration bounds");
        var car=new GameObject();car.transform.position=new Vector3(50,100,60);
        var storage=new VehicleStorage(car,false,0);
        var root=ZNetScene.instance.objects.Values.Single();var container=root.GetComponent<Container>();var data=root.GetComponent<ZNetView>().data;
        Check(data.Persistent&&data.GetPosition().y==10.15f,"persistent grounded recovery position while flying");
        Check(!root.GetComponent<Renderer>().enabled&&!root.GetComponent<Collider>().enabled,"hidden cargo cannot collide with car");
        Check(!root.GetComponent<WearNTear>().m_noSupportWear&&!root.GetComponent<WearNTear>().m_noRoofWear,"carried chest has no support/rain damage");
        for(int i=0;i<16;i++)container.inventory.items.Add(new Item{m_gridPos=new Vector2i(i%6,3),stack=i+1,custom="custom-"+i});
        container.inventory.m_onChanged();var items=container.inventory.items.ToArray();
        Check(!storage.CanResize(2)&&!storage.Resize(2)&&storage.Layout==0,"overfull downgrade refused");
        Check(items.Select((item,i)=>item.m_gridPos.y==3).All(v=>v),"failed downgrade leaves positions intact");
        Check(storage.Resize(1)&&container.inventory.GetHeight()==3,"legal downgrade succeeds");
        Check(items.Select((item,i)=>ReferenceEquals(item,container.inventory.items[i])&&item.m_gridPos.x==i%6&&item.m_gridPos.y==i/6&&item.stack==i+1&&item.custom=="custom-"+i).All(v=>v),"repack retains item identity, stacks and custom data");
        Check(data.items.Count==16,"repack saved to existing world chest");
        Check(storage.Open("350Z cargo")&&InventoryGui.instance.current==container&&container.inventory.GetName()=="350Z cargo","native inventory opens with cargo title");
        Check(!storage.CanResize(0)&&!storage.Resize(0),"resize blocked during inventory drag session");
        car.transform.position=new Vector3(250,200,360);storage.Tick();
        Check(data.GetPosition().x==250&&data.GetPosition().z==358.7f,"moving vehicle updates persistent sector position");
        storage.Release();storage.Release();
        Check(!data.deleted&&data.items.Count==16&&ZNetScene.instance.created==1,"nonempty release keeps same chest, no copied items");
        Check(container.inventory.GetHeight()==4&&InventoryGui.instance.current==null,"release closes inventory and restores vanilla dimensions");
        Check(root.GetComponent<Renderer>().enabled&&root.GetComponent<Collider>().enabled&&root.GetComponent<WearNTear>().m_noSupportWear,"release restores physical chest");
        Check(root.transform.position.y==data.GetPosition().y,"recovered chest is grounded");
        ZNetScene.instance=new ZNetScene();
        var empty=new VehicleStorage(car,true,3);var emptyRoot=ZNetScene.instance.objects.Values.Single();
        Check(empty.Capacity==32,"H2 inventory capacity");empty.Release();empty.Release();
        Check(emptyRoot.GetComponent<ZNetView>().data.deleted&&ZNetScene.instance.objects.Count==0,"empty cargo removed once");
        var parked=new VehicleStorage(car,false,2);var parkedRoot=ZNetScene.instance.objects.Values.Single();var saved=parkedRoot.GetComponent<ZNetView>().data;
        parkedRoot.GetComponent<Container>().inventory.items.Add(new Item{stack=42,custom="parked"});parkedRoot.GetComponent<Container>().inventory.m_onChanged();
        UnityEngine.Object.Destroy(parkedRoot);ZNetScene.instance.objects.Clear();var created=ZNetScene.instance.created;
        parked.Tick();Check(!parked.CanResize(3)&&!parked.Open("closed")&&ZNetScene.instance.created==created,"unloaded cargo is never replaced or resized");
        car.transform.position=new Vector3(400,220,500);parked.Tick();
        Check(saved.GetPosition().x==400&&saved.GetPosition().z==498.7f,"unloaded cargo record follows car across sectors without cloning inventory");
        saved.owner=false;car.transform.position=new Vector3(420,220,500);parked.Tick();
        Check(saved.GetPosition().x==400,"unloaded cargo position is written only by its owner");saved.owner=true;
        var loaded=ZNetScene.instance.GetPrefab("piece_chest").Clone(saved.GetPosition(),saved.GetRotation());
        ZNetScene.instance.objects.Clear();loaded.GetComponent<ZNetView>().data=saved;
        loaded.GetComponent<Container>().inventory.m_onChanged=()=>saved.items=loaded.GetComponent<Container>().inventory.items.ToList();
        ZNetScene.instance.objects[saved.m_uid]=loaded;parked.Tick();
        Check(parked.Count==1&&loaded.GetComponent<Container>().inventory.items[0].stack==42&&loaded.GetComponent<Container>().inventory.GetHeight()==2,"zone reload loads contents before restoring cargo size");
        UnityEngine.Object.Destroy(loaded);ZNetScene.instance.objects.Clear();parked.Release();
        Check(!saved.deleted&&saved.items.Count==1,"unloaded release retains persistent cargo");
        var quit=new VehicleStorage(car,false,0);var quitRoot=ZNetScene.instance.objects.Values.Single();var quitData=quitRoot.GetComponent<ZNetView>().data;
        quitRoot.GetComponent<Container>().inventory.items.Add(new Item{stack=7});quitRoot.GetComponent<Container>().inventory.m_onChanged();
        quit.Open("quit");Player.m_localPlayer=null;ZNetScene.instance=null;quit.Release();
        Check(!quitData.deleted&&quitData.items.Count==1,"world teardown retains saved cargo without native UI calls");
        ZNetScene.instance=new ZNetScene();Player.m_localPlayer=new Player();
        var previousWorld=new VehicleStorage(car,false,0);var previousRoot=ZNetScene.instance.objects.Values.Single();
        var previousData=previousRoot.GetComponent<ZNetView>().data;var previousPosition=previousData.GetPosition();
        ZDOMan.instance=new ZDOMan();ZNetScene.instance=new ZNetScene();car.transform.position=new Vector3(900,900,900);
        previousWorld.Tick();previousWorld.Release();
        Check(previousData.GetPosition().x==previousPosition.x&&!previousData.deleted,"old vehicle cannot mutate cargo after world switch");
        Check(!previousRoot.GetComponent<Renderer>().enabled,"old-world cleanup does not restore native objects in a different world");
        var durable=new VehicleStorage(car,false,0);var durableRoot=ZNetScene.instance.objects.Values.Single();var durableData=durable.Data;
        VehiclePersistence.Save(durableData,"mw-bmwm3gtr",car.transform,2,true,"{}");
        Check(VehiclePersistence.IsVehicle(durableData)&&VehiclePersistence.Profile(durableData)=="mw-bmwm3gtr","persistent metadata uses generic profile identity");
        Check(VehiclePersistence.ValidPose(durableData)&&VehiclePersistence.Trunk(durableData)==2&&VehiclePersistence.WasDriven(durableData),"persistent pose and trunk/driven metadata retained");
        durable.Release(true);Check(!durableData.deleted&&VehiclePersistence.IsVehicle(durableData),"empty vehicle anchor survives world teardown");
        var profile=new CarProfile();profile.capabilities.showroom=true;profile.rig.trunkApproachZ=1.3f;
        var restored=new VehicleStorage(car,profile,durableData);
        Check(restored.Data==durableData&&ZNetScene.instance.objects.Count==1,"restoration reuses the same cargo ZDO without cloning");
        restored.Release();
        Check(!VehiclePersistence.IsVehicle(durableData)&&durableData.deleted,"explicit empty vehicle removal clears discriminator and native anchor");
        var cargoVehicle=new VehicleStorage(car,false,0);var cargoRoot=ZNetScene.instance.objects.Values.Single();
        cargoRoot.GetComponent<Container>().inventory.items.Add(new Item{stack=19,custom="world-snapshot"});
        cargoRoot.GetComponent<Container>().inventory.m_onChanged();
        VehiclePersistence.Save(cargoVehicle.Data,"miata",car.transform,0,false,"{}");
        cargoVehicle.Open("persist");cargoVehicle.Release(true);
        Check(InventoryGui.instance.current==null&&!cargoVehicle.Data.deleted,"teardown closes open cargo UI while preserving its world identity");
        VehicleStorage.Hide(cargoRoot);VehicleStorage.Hide(cargoRoot);
        var cargoRestored=new VehicleStorage(car,profile,cargoVehicle.Data);cargoRestored.Release();
        Check(!VehiclePersistence.IsVehicle(cargoVehicle.Data)&&cargoVehicle.Data.items.Single().stack==19&&!cargoVehicle.Data.deleted,"explicit removal preserves nonempty cargo in the same vanilla record");
        Check(cargoRoot.GetComponent<Renderer>().enabled&&cargoRoot.GetComponent<Collider>().enabled,"early cargo hide and reattach preserve original visible states");
        var invalid=new ZDO();var badCar=new GameObject();badCar.transform.position=new Vector3(float.NaN,0,0);
        VehiclePersistence.Save(invalid,"miata",badCar.transform,0,false,"{}");
        Check(!VehiclePersistence.ValidPose(invalid),"nonfinite persistent pose rejected before restore");
        var legacy=new ZDO();legacy.Set(VehiclePersistence.LegacyModel,1);legacy.Set("nfvu2_position",new Vector3(12,34,56));
        legacy.Set("nfvu2_rotation",Quaternion.identity);legacy.Set("nfvu2_layout",3);legacy.Set("nfvu2_driven",true);
        Check(VehiclePersistence.IsVehicle(legacy)&&VehiclePersistence.Profile(legacy)==CarCatalog.StockId,"upstream v1 stock vehicle identity remains readable");
        Check(VehiclePersistence.Location(legacy).z==56&&VehiclePersistence.Trunk(legacy)==3&&VehiclePersistence.WasDriven(legacy)&&VehiclePersistence.Settings(legacy)=="{}","upstream pose layout and driven state retained without invented build data");
        legacy.Set(VehiclePersistence.LegacyModel,2);Check(VehiclePersistence.Profile(legacy)=="h2","upstream v1 H2 identity maps to SUV profile");
        VehiclePersistence.Save(legacy,"rx7",car.transform,0,false,"{}");
        Check(legacy.GetInt(VehiclePersistence.LegacyModel)==0&&VehiclePersistence.Profile(legacy)=="rx7","generic snapshot migrates old discriminator after publishing metadata");
        VehiclePersistence.Forget(legacy);Check(!VehiclePersistence.IsVehicle(legacy),"removal cannot resurrect a legacy vehicle discriminator");
        legacy=new ZDO();legacy.Set(VehiclePersistence.LegacyModel,2);legacy.Set("nfvu2_layout",2);legacy.Set("nfvu2_position",new Vector3(12,34,56));legacy.Set("nfvu2_rotation",Quaternion.identity);
        VehiclePersistence.UpgradeLegacy(legacy);
        Check(VehiclePersistence.Profile(legacy)=="h2"&&VehiclePersistence.Settings(legacy)=="{}"&&VehiclePersistence.Location(legacy).z==56&&VehiclePersistence.Trunk(legacy)==2&&!VehiclePersistence.IsLegacy(legacy),"headless legacy upgrade retains original pose and capacity without a Transform");
        var distantData=new ZDO{items=new System.Collections.Generic.List<Item>{new Item{stack=31,custom="distant"}}};
        distantData.Set(VehiclePersistence.Model,"miata");VehicleStorage.RemoveSaved(distantData);
        Check(!VehiclePersistence.IsVehicle(distantData)&&!distantData.deleted&&distantData.items.Single().stack==31,"distant removal retains native inventory without requiring a loaded container");
        distantData.Set(VehiclePersistence.Model,"miata");distantData.owner=false;VehicleStorage.RemoveSaved(distantData);
        Check(VehiclePersistence.IsVehicle(distantData),"nonowner distant removal leaves record untouched");
        ZNetScene.instance=new ZNetScene();var busyStorage=new VehicleStorage(car,false,0);var busyRoot=ZNetScene.instance.objects.Values.Single();
        VehiclePersistence.Save(busyStorage.Data,"miata",car.transform,0,false,"{}");busyStorage.Open("busy");
        bool busyRejected=false;try{VehicleStorage.RemoveSaved(busyStorage.Data);}catch(InvalidOperationException){busyRejected=true;}
        Check(busyRejected&&VehiclePersistence.IsVehicle(busyStorage.Data),"busy loaded cargo refuses removal before metadata changes");
        InventoryGui.instance.Hide();VehicleStorage.RemoveSaved(busyStorage.Data);
        Check(busyStorage.Data.deleted&&!VehiclePersistence.IsVehicle(busyStorage.Data),"loaded empty saved vehicle removes its existing native anchor");
        Console.WriteLine(checks+" storage checks passed (native API doubles; game save/UI tests still required).");
    }
}
